"""物質1：いろいろな物質とその性質（ワーク p50〜59。物質分野の教科書本文の写真は無いので、ワークと教科書のサイエンス資料 p126〜127・130〜131 を根拠にする）"""
from fractions import Fraction as F
from kbank import T, C, SEQ, N, S, R
from sci import unit

MAJ = 'いろいろな物質とその性質'

def kubetsu():
    u = unit('kubetsu', '物質の区別', MAJ, {50, 51, 58, 59},
             '2026-10-05 Claude作成。理科ワークp50〜51（教科書チェック①〜⑤・探Q実験1）・p58基本①②と○×①②・p59力だめし①と、教科書p126〜127・130〜131（サイエンス資料：実験の注意・いろいろな実験器具・薬品のとり方）を写真で確認して作成。物質分野の教科書本文（p132以降）の写真は無いため、用語と性質はワークの問題とまとめを根拠にした。')
    q = u.q
    q(50, '①(1)', '物体と物質', '食器のように、使う目的や形などでものを区別するときの名称を何というか。', T('物体', 'ぶったい'), 'ワークp50①(1)：物体。', near=['物質'])
    q(50, '①(2)', '物体と物質', 'ガラスやプラスチックのように、材料でものを区別するときの名称を何というか。', T('物質', 'ぶっしつ'), 'ワークp50①(2)：物質。', near=['物体'])
    q(50, '①(3)', '物体と物質', '「鉄製のくぎ」で、物体にあたるのはどれか。', T('くぎ', '釘', 'クギ'), 'ワークp50①(3)①：物体はくぎ、物質は鉄。', near=['鉄'])
    q(50, '①(3)', '物体と物質', '「鉄製のくぎ」で、物質にあたるのはどれか。', T('鉄', 'てつ'), 'ワークp50①(3)②：鉄。', near=['くぎ'])
    for obj, mat, wrong in [('ガラスのコップ', 'ガラス', 'コップ'), ('アルミニウムはく', 'アルミニウム', 'はく'), ('プラスチックのペットボトル', 'プラスチック', 'ペットボトル'), ('木の机', '木', '机')]:
        q(50, '①(3)', '物体と物質', f'「{obj}」で、物質にあたるのはどれか。', T(mat), f'ワークp50①：使う目的や形で区別するときは物体（{wrong}）、材料で区別するときは物質（{mat}）。', near=[wrong])
    q(50, '②(1)A', 'ガスバーナー', 'ガスバーナーの2つのねじのうち、上にあって空気の量を調節するねじを何というか。', T('空気調節ねじ', 'くうきちょうせつねじ'), 'ワークp50②(1)A：空気調節ねじ。', near=['ガス調節ねじ'])
    q(50, '②(1)B', 'ガスバーナー', 'ガスバーナーの2つのねじのうち、下にあってガスの量を調節するねじを何というか。', T('ガス調節ねじ', 'がすちょうせつねじ'), 'ワークp50②(1)B：ガス調節ねじ。', near=['空気調節ねじ'])
    q(50, '②(2)', 'ガスバーナー', 'ガスバーナーの元栓を開ける前に、空気調節ねじとガス調節ねじをどのような状態にしておくか。', R((1, ['閉', 'しめ', 'しま', '締'])), 'ワークp50②(2)：2つのねじが軽くしまっている状態にしておく。', example='軽くしまっている状態')
    q(50, '②(3)', 'ガスバーナー', 'ガスバーナーに火をつけるときの手順を正しい順に並べよう。\nア ガス調節ねじをゆるめて火をつける　イ 元栓を開ける　ウ 空気調節ねじをゆるめて炎の色を調節する　エ ガス調節ねじを回して炎の大きさを調節する', SEQ(list('イアエウ')), 'ワークp50②(3)：①元栓（コック）を開ける→②火を近づけ、ガス調節ねじをゆるめて火をつける→③ガス調節ねじで炎の大きさ→④空気調節ねじで炎の色。', near=['イアウエ', 'アイエウ'])
    q(50, '②(3)', 'ガスバーナー', 'ガスバーナーに火をつけるとき、ガスライター（マッチ）の火は、どの方向から近づけるか。', T('ななめ下', 'ななめしたから', 'ななめ下から', '斜め下', '斜め下から'), 'ワークp50②(3)②：ガスライター（マッチ）に火をつけ、ななめ下から火を近づける。', near=['真上', '上'])
    q(50, '②(4)', 'ガスバーナー', 'ガスバーナーの炎の大きさは、およそ何cmくらいにするか。', N(10, ['cm', 'センチ']), 'ワークp50②(4)：イ 10 cm。', near=['5', '15'])
    q(50, '②(5)', 'ガスバーナー', 'ガスバーナーの炎の色は、赤い色と青い色のどちらにするか。', T('青い色', '青色', '青', 'あお', '青い'), 'ワークp50②(5)：青い色（安定した炎）。', near=['赤い色', '赤色'])
    q(58, '①(1)', 'ガスバーナー', 'ガスバーナーの炎が赤色（オレンジ色）のとき、どちらのねじを回して青い安定した炎にするか。', T('空気調節ねじ', 'くうきちょうせつねじ'), 'ワークp58①(1)：空気調節ねじ（A）を回して空気の量をふやし、青い安定した炎にする。', near=['ガス調節ねじ'])
    q(58, '①(1)', 'ガスバーナー', '炎が赤色のときは、空気の量が足りないか、多すぎるか。', T('足りない', 'たりない', '少ない', '不足', '足りない（少ない）'), 'ワークp58①(1)：空気調節ねじを開いて空気を入れると青い安定した炎になる。赤色は空気が足りない状態。', near=['多すぎる'])
    q(58, '○×①', 'ガスバーナー', '「ガスバーナーで炎の大きさを調節するときは、空気調節ねじを回す。」この文の誤りを直すと、空気調節ねじは何になるか。', T('ガス調節ねじ', 'がすちょうせつねじ'), 'ワークp58○×①：ガス調節ねじ。', near=['空気調節ねじ'])
    q(50, '②(6)', 'ガスバーナー', '火を消すときに、ねじA（空気調節ねじ）、ねじB（ガス調節ねじ）、コック、元栓を閉じる順を記号で並べよう。', SEQ(['A', 'B', 'コック', '元栓']), 'ワークp50②(6)：ア A→B→コック→元栓（つけるときの逆の順）。', near=['B→A→コック→元栓'])
    q(50, '③(1)', '白い粉末', '砂糖・かたくり粉・食塩をそれぞれ水に入れてよく振ったとき、ほとんどがとけ残ったのはどれか。', T('かたくり粉', 'かたくりこ', '片栗粉'), 'ワークp51③(1)：かたくり粉。', near=['砂糖', '食塩'])
    q(51, '③(2)', '白い粉末', '砂糖・かたくり粉・食塩を炎の中に入れたとき、燃えて炭になったものをすべて答えよう。', S(('砂糖', 'さとう'), ('かたくり粉', 'かたくりこ', '片栗粉')), 'ワークp51③(2)：砂糖とかたくり粉。食塩は燃えない。', near=['砂糖'])
    q(51, '③(2)', '白い粉末', '砂糖・かたくり粉・食塩のうち、加熱しても燃えないのはどれか。', T('食塩', 'しょくえん', '塩'), 'ワークp51③・p59①(1)：食塩は加熱してもこげない。', near=['砂糖'])
    q(51, '③(3)', '石灰水', '砂糖が燃えたあと、集気びんをよく振ると石灰水はどのように変化するか。', R((1, ['白', 'しろ']), (1, ['にご', '濁'])), 'ワークp51③(3)：白くにごる。', example='白くにごる。')
    q(51, '③(4)', '白い粉末', '水にほとんどとけず、加熱すると燃えて炭になり、燃えたあと石灰水が白くにごった物質Xは何か。', T('かたくり粉', 'かたくりこ', '片栗粉'), 'ワークp51③(4)：かたくり粉。', near=['砂糖'])
    q(51, '③(4)', '白い粉末', '水によくとけ、加熱すると燃えて炭になった白い粉末は、砂糖・かたくり粉・食塩のどれか。', T('砂糖', 'さとう'), 'ワークp51③：砂糖は水によくとけ、燃えて炭になる。', near=['かたくり粉', '食塩'])
    q(51, '③(4)', '白い粉末', '水によくとけ、加熱しても燃えなかった白い粉末は、砂糖・かたくり粉・食塩のどれか。', T('食塩', 'しょくえん', '塩'), 'ワークp51③：食塩は水によくとけるが、燃えない。', near=['砂糖'])
    q(59, '①(5)', '白い粉末', '味や粒のようす、手ざわりを調べずに、砂糖とかたくり粉を区別する方法を簡潔に書こう。', R((1, ['水']), (1, ['とけ', '溶け', 'とか', '溶か'])), 'ワークp59①(5)：水に入れてとけるかどうかを調べる（砂糖はとけ、かたくり粉はほとんどとけない）。', example='水に入れてとけるかどうか調べる。')
    q(51, '④(1)', '有機物', 'ろうを燃焼さじにのせて石灰水の入った集気びんの中で燃やすと、内側がくもった。これは、ろうが燃えて何が発生したためか。', T('水', 'みず', '水蒸気'), 'ワークp51④(1)：水。', near=['二酸化炭素'])
    q(51, '④(2)', '有機物', 'ろうを燃やしたあと燃焼さじをとり出して集気びんをよく振ると、石灰水が白くにごった。ろうが燃えて何が発生したためか。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp51④(2)：二酸化炭素。', near=['水', '酸素'])
    q(51, '④(3)', '有機物', '二酸化炭素が発生するのは、ろうが何という成分をふくんでいるからか。', T('炭素', 'たんそ'), 'ワークp51④(3)：炭素。', near=['水素', '酸素'])
    q(51, '④(4)', '有機物', '炭素をふくみ、燃えて二酸化炭素を発生する物質を何というか。', T('有機物', 'ゆうきぶつ'), 'ワークp51④(4)：有機物。', near=['無機物'])
    q(51, '④(5)', '無機物', '有機物以外の物質を何というか。', T('無機物', 'むきぶつ'), 'ワークp51④(5)：無機物。', near=['有機物'])
    q(51, '④(6)', '無機物', 'スチールウール（鉄）を燃やすと、二酸化炭素は発生するか、しないか。', T('しない', '発生しない', 'しません'), 'ワークp51④(6)：しない。', near=['する'])
    q(51, '④(7)', '無機物', '鉄は、有機物・無機物のどちらか。', T('無機物', 'むきぶつ'), 'ワークp51④(7)：無機物。', near=['有機物'])
    q(58, '①(2)', '有機物', '砂糖は炭素をふくんでいて、加熱すると燃える。このような物質を何というか。', T('有機物', 'ゆうきぶつ'), 'ワークp58①(2)：有機物。', near=['無機物'])
    q(58, '○×②', '有機物', '「かたくり粉を加熱すると、燃えて二酸化炭素と水が発生する。」この文は正しいか。正しければ〇、誤りなら正しい言葉を書こう。', T('〇', '○', 'O', 'o', '正しい'), 'ワークp58○×②：○。', near=['酸素'])
    q(59, '①(3)', '有機物', '砂糖やかたくり粉を加熱したときに二酸化炭素が発生したのは、何がふくまれているからか。', T('炭素', 'たんそ'), 'ワークp59①(3)：炭素がふくまれているから（これをふくむ物質を有機物という）。', near=['酸素'])
    q(59, '①(4)', '有機物', '砂糖やかたくり粉を集気びんの中で加熱すると、集気びんの内側がくもった。何が発生したためか。', T('水', 'みず', '水蒸気'), 'ワークp59①(4)：水。', near=['二酸化炭素'])
    q(51, '④(4)', '有機物と無機物', '次のうち、有機物をすべて選ぼう。\nア 砂糖　イ 食塩　ウ ろう　エ 鉄', C('アウ'), 'ワークp51・59：砂糖・ろうは燃えて二酸化炭素を出す有機物。食塩・鉄は無機物。', near=['ア', 'ウ'])
    q(51, '⑤(1)①', '金属', 'アルミニウムや銅、鉄などの物質を何というか。', T('金属', 'きんぞく'), 'ワークp51⑤(1)①：金属。', near=['非金属'])
    q(51, '⑤(1)②', '非金属', '金属以外のプラスチックやガラス、木などの物質を何というか。', T('非金属', 'ひきんぞく'), 'ワークp51⑤(1)②：非金属。', near=['金属'])
    q(51, '⑤(2)①', '金属の性質', '金属に共通する性質のうち、電気を通すことのほかに、何をよく伝えるか。', T('熱', 'ねつ'), 'ワークp51⑤(2)①：熱をよく伝える。', near=['光'])
    q(51, '⑤(2)②', '金属の性質', '金属をみがくと出る、特有のかがやきを何というか。', T('金属光沢', 'きんぞくこうたく', '光沢'), 'ワークp51⑤(2)②・p58②(4)：金属光沢。')
    q(51, '⑤(2)③', '展性', '金属がたたくと広がる性質を何というか。', T('展性', 'てんせい'), 'ワークp51ポイント：③（たたくと広がる）の性質を展性という。', near=['延性'])
    q(51, '⑤(2)④', '延性', '金属が引っぱるとのびる性質を何というか。', T('延性', 'えんせい'), 'ワークp51ポイント：④（引っぱるとのびる）の性質を延性という。', near=['展性'])
    q(51, '⑤(3)', '磁石', 'スチール缶とアルミニウム缶に磁石を近づけた。磁石につくのはどちらか。', T('スチール缶', 'すちーるかん', 'スチール'), 'ワークp51⑤(3)：①スチール缶はつく、②アルミニウム缶はつかない。', near=['アルミニウム缶'])
    q(51, '⑤(4)', '磁石', '磁石につくことは、金属に共通の性質といえるか。', T('いえない', 'いえません', '共通ではない'), 'ワークp51⑤(4)：いえません（アルミニウムや銅は磁石につかない）。', near=['いえる'])
    q(58, '②(1)', '金属の性質', 'ガラスのコップ・鉄くぎ・アルミニウムはく・ペットボトルのうち、電気を通したものをすべて答えよう。', S(('鉄くぎ', '鉄', 'てつくぎ'), ('アルミニウムはく', 'アルミニウム', 'アルミはく')), 'ワークp58②(1)：B（鉄くぎ）とC（アルミニウムはく）。金属は電気を通す。', near=['鉄くぎ'])
    q(58, '②(2)', '金属の性質', 'ガラスのコップ・鉄くぎ・アルミニウムはく・ペットボトルのうち、磁石についたものはどれか。', T('鉄くぎ', '鉄', 'てつくぎ', 'B'), 'ワークp58②(2)：B（鉄くぎ）。', near=['アルミニウムはく'])
    q(58, '②(3)', '金属の性質', '金属に共通する性質を、次からすべて選ぼう。\nア たたくと広がる　イ 熱を伝えにくい　ウ 電気をよく通す　エ 磁石につく', C('アウ'), 'ワークp58②(3)：ア、ウ。熱はよく伝える。磁石につくのは鉄など一部の金属。', near=['ア', 'ウ', 'アウエ'])
    q(58, '②(5)', '非金属', '次のうち、非金属をすべて選ぼう。\nア ガラス　イ 銅　ウ プラスチック　エ 木　オ 鉄', C('アウエ'), 'ワークp51⑤(1)：金属以外のプラスチックやガラス、木などは非金属。', near=['アウ', 'アエ'])
    q(59, '①(2)', '石灰水', '石灰水が白くにごることから、何という気体が発生したことがわかるか。', T('二酸化炭素', 'にさんかたんそ', 'CO2', 'CO₂'), 'ワークp59①(2)：二酸化炭素。', near=['酸素'])
    q(59, '①(1)', '白い粉末', '砂糖・食塩・かたくり粉のいずれかである白い粉末A〜Cを燃焼さじで加熱すると、Aは変化しなかったが、BとCはこげた。Aは何か。', T('食塩', 'しょくえん', '塩'), 'ワークp59①(1)：A＝食塩（加熱してもこげない）。', near=['砂糖'])
    q(51, '探Q実験1', '謎の物質Xの正体', '燃焼さじで加熱して火がついたら、燃焼さじを何の入った集気びんに入れるか。', T('石灰水', 'せっかいすい'), 'ワークp50探Q実験1②：火がついたら、燃焼さじを石灰水の入った集気びんに入れ、火が消えたらとり出す。', near=['水'])
    q(51, '探Q実験1', '謎の物質Xの正体', '探Q実験1で、火が消えたあと燃焼さじをとり出し、集気びんにふたをしてどうするか。', T('よく振る', '振る', 'ふる', 'よくふる'), 'ワークp50探Q実験1③：集気びんにふたをしてよく振る。')
    # 実験器具（教科書p126〜127・130〜131 サイエンス資料）
    q(50, '②(1)', '実験の注意', '実験中に保護眼鏡などを着用するのは、何をするためか。教科書のチェックリストの言葉で答えよう。', R((1, ['実験に適した', '安全', '目', '身'])), '教科書p126実験中のチェック：保護眼鏡の着用など、実験に適した身なりをしていますか。', tb=126, tbnote='実験のチェックリスト', example='実験に適した身なりにするため')
    q(50, '②(6)', '実験の注意', '実験後、ガスの元栓や水道の蛇口はどうするか。', R((1, ['しめ', '閉め', '締め'])), '教科書p126実験後：ガスの元栓や水道の蛇口をしっかりとしめましたか。', tb=126, tbnote='実験後', example='しっかりとしめる。')
    q(50, '③(1)', '薬品のとり方', '固体（粉末）の薬品を電子てんびんではかるとき、てんびんの上にのせるものは何か。', T('薬包紙', 'やくほうし', '折り目をつけた薬包紙'), '教科書p131：折り目をつけた薬包紙をのせる。', tb=131, tbnote='固体（粉末）薬品のとり方', near=['ろ紙'])
    q(50, '③(1)', '薬品のとり方', '液体の薬品をびんから注ぐとき、ラベルをどちら側にするか。', T('上', 'うえ', '上にする', '上側'), '教科書p131：注ぐときはラベルを上にする。ガラス棒を伝わらせて少しずつ入れる。', tb=131, tbnote='液体薬品のとり方', near=['下'])
