def fs(x):
    """分数・小数を、問題文と答えに使う短い小数の文字列にする（割り切れるものだけを使う）"""
    x = F(x)
    s = f'{float(x):.6f}'.rstrip('0').rstrip('.')
    assert F(s) == x, (x, s)
    return s

