    q(57, 'とっくん(2)', '密度の比較', '物質A（90 g、10 cm³）、B（76 g、4 cm³）、C（120 g、15 cm³）のうち、同じ体積にしたとき質量がいちばん大きくなるのはどれか。', T('B'), '密度を比べる。A 9、B 19、C 8 g/cm³。同じ体積なら密度が大きいほど質量が大きい→B（ワークp57とっくん(2)②）。', near=['A', 'C'])
    q(57, 'とっくん(2)', '密度の比較', '同じ3つの物質A（9 g/cm³）、B（19 g/cm³）、C（8 g/cm³）のうち、同じ質量にしたとき体積がいちばん大きくなるのはどれか。', T('C'), '同じ質量なら密度が小さいほど体積が大きい→C（ワークp57とっくん(2)①）。', near=['B'])
    q(57, 'とっくん(2)', '密度の比較', '同じ3つの物質A（9 g/cm³）、B（19 g/cm³）、C（8 g/cm³）のうち、水銀（13.5 g/cm³）に沈むものはどれか。', T('B'), '水銀より密度が大きいものは沈む→B（ワークp57とっくん(2)③）。', near=['A', 'C'])
    # 小数の計算（ワークp54〜55）
    for a, b, op in [('1.54', '3.2', '×'), ('0.3', '2.6', '×'), ('20.8', '3.4', '×'), ('1.28', '0.4', '÷'), ('8.82', '6.3', '÷'), ('77.5', '1.55', '÷')]:
        val = F(a) * F(b) if op == '×' else F(a) / F(b)
        q(54 if op == '×' else 55, '①', '小数の計算', f'次の計算をしよう。\n{a} {op} {b}', N(fs(val)), f'ワークp54〜55の筆算のしかた：{a} {op} {b} ＝ {fs(val)}', near=[fs(val * 10), fs(val / 10)])
    q(55, '②', '四捨五入', '2.43を、四捨五入して小数第1位までの数にしよう。', N('2.4'), 'ワークp55②(2)：小数第2位を四捨五入する。2.43→2.4。', near=['2.5'])
    q(55, 'とっくん(1)', '小数の計算', '縦2.6 cm、横3.4 cmの長方形の面積は何cm²か。小数第2位を四捨五入して小数第1位まで答えよう。', N('8.8', ['cm²', 'cm2']), 'ワークp55とっくん(1)：2.6×3.4＝8.84≒8.8 cm²。', near=['8.84', '6'])
    for name, v in [('金', 10), ('エタノール', 100), ('氷', 100), ('鉛', 2)]:
        m = F(DENS[name]) * v
        q(52, '①(3)', '表を使った計算', f'{name}の密度は{DENS[name]} g/cm³である。{name}{v} cm³の質量は何gか。', N(fs(m), ['g', 'グラム']), f'質量＝密度×体積＝{DENS[name]}×{v}＝{fs(m)} g（密度はワークp52の表）。', near=[fs(F(v) / F(DENS[name]))] if (F(v) / F(DENS[name])).denominator in (1, 2, 4, 5, 10) else [])
    q(52, '①(3)', '浮き沈み', '食用油の密度は0.91〜0.92 g/cm³である。食用油を水に入れると、浮くか沈むか。', T('浮く', 'うく'), 'ワークp52の表：水1.00 g/cm³より小さいので浮く。', near=['沈む'])
    q(52, '①(3)', '浮き沈み', '金（19.3 g/cm³）でできた物体を水銀（13.5 g/cm³）に入れると、浮くか沈むか。', T('沈む', 'しずむ'), 'ワークp52の表：金は水銀より密度が大きいので沈む。', near=['浮く'])
    return u
